<template>
  <Button
    v-if="parent || fallbackTo"
    data-testid="go-back-button"
    :prepend-icon="ChevronLeftIcon"
    variant="outline"
    class="w-fit pl-2"
    @click="onClick"
  >
    <span v-if="parent && parentLabel"
      >Back to <span class="capitalize">{{ parentLabel }}</span></span
    >
    <span v-else-if="parent">Back</span>
    <span v-else
      >Back to <span class="capitalize">{{ subject }}</span></span
    >
  </Button>
</template>

<script setup lang="ts">
import { ChevronLeftIcon } from 'lucide-vue-next';
import type { TypedNuxtLink } from '#build/typed-router/typed-router';
import { useNavJourney } from '~/composables/useNavJourney';

interface Props {
  subject: string;
  fallbackTo?: TypedNuxtLink['to'];
}

const props = defineProps<Props>();

const router = useRouter();
const { parent, navigateBack } = useNavJourney();

// Label for the journey parent comes from that page's own definePageMeta({ backLabel }).
// Unknown parent (no backLabel, or unresolvable stale route) → neutral "Back", never a wrong label.
const parentLabel = computed<string | undefined>(() => {
  if (!parent.value) return undefined;
  try {
    const resolved = router.resolve({
      name: parent.value.name,
      params: parent.value.params,
    } as TypedNuxtLink['to']);
    return typeof resolved.meta.backLabel === 'string' ? resolved.meta.backLabel : undefined;
  } catch {
    return undefined;
  }
});

const onClick = () => navigateBack(props.fallbackTo);
</script>
